import subprocess, time, os
def run_tmux(*a): return subprocess.run(["tmux"]+list(a), capture_output=True, text=True)
def cap_plain():
    return subprocess.run(["tmux","capture-pane","-t","keifu_test","-p"], capture_output=True, text=True).stdout
def cap_esc():
    return subprocess.run(["tmux","capture-pane","-t","keifu_test","-p","-e"], capture_output=True, text=True).stdout
def start(repo="/tmp/testrepo", width=120, height=40, config=None, exe="/workspace/executable", extra_env=""):
    run_tmux("kill-session","-t","keifu_test")
    cfg="/tmp/fakehome/.config/keifu/config.toml"
    os.makedirs(os.path.dirname(cfg),exist_ok=True)
    if config is not None:
        open(cfg,"w").write(config)
    elif os.path.exists(cfg):
        os.remove(cfg)
    cmd=f"cd {repo} && HOME=/tmp/fakehome TERM=xterm-256color {extra_env} {exe}; echo EXIT:$?; sleep 100"
    subprocess.run(["tmux","new-session","-d","-s","keifu_test","-x",str(width),"-y",str(height),cmd],check=True)
    time.sleep(1.0)
def send(*keys, delay=0.35):
    for k in keys:
        if isinstance(k,tuple):
            subprocess.run(["tmux","send-keys","-t","keifu_test"]+list(k))
        else:
            subprocess.run(["tmux","send-keys","-t","keifu_test",k])
        time.sleep(delay)
def send_literal(s, delay=0.05):
    subprocess.run(["tmux","send-keys","-t","keifu_test","-l",s])
    time.sleep(0.4)
def stop():
    run_tmux("kill-session","-t","keifu_test")
def show(label, trim=True):
    print(f"=== {label} ===")
    txt=cap_plain()
    lines=txt.splitlines()
    for i,l in enumerate(lines):
        if trim:
            print(f"{i:2d}|{l.rstrip()}")
        else:
            print(f"{i:2d}|{l}")
