fn build_search_lines(app: &App, inner_width: usize) -> (u16, Vec<Line<'static>>) {
    let input_line = if app.search_query.is_empty() {
        Line::from(vec![Span::raw("  "), Span::styled("_", Style::default().fg(Color::Cyan))])
    } else {
        Line::from(vec![
            Span::raw("  "),
            Span::styled(app.search_query.clone(), Style::default().fg(Color::White).add_modifier(Modifier::UNDERLINED)),
            Span::styled("_", Style::default().fg(Color::Cyan)),
        ])
    };
    if app.search_query.is_empty() {
        let lines = vec![input_line, Line::from(Span::styled("  Enter: confirm  Esc: cancel", Style::default().fg(Color::DarkGray)))];
        return (4, lines);
    }
    if app.search_results.is_empty() {
        let lines = vec![input_line, Line::from(Span::styled("  No matches", Style::default().fg(Color::DarkGray)))];
        // Original style for No matches might be default; keep dark gray as hint style? will refine from esc capture later.
        return (4, lines);
    }
    let total = app.search_results.len();
    let visible_count = total.min(7);
    let selected = app.search_index.min(total - 1);
    let start = if selected >= 7 { selected - 6 } else { 0 };
    let end = (start + visible_count).min(total);
    let mut lines = Vec::new();
    lines.push(input_line);
    lines.push(Line::from(Span::styled("─".repeat(inner_width), Style::default().fg(Color::DarkGray))));
    for idx in start..end {
        let b = &app.search_results[idx];
        let is_selected = idx == selected;
        let is_first_visible = idx == start;
        let is_last_visible = idx == end - 1;
        let prefix_char = if is_selected {
            if is_last_visible && end < total { '▼' } else { '▶' }
        } else if is_first_visible && start > 0 {
            '↑'
        } else if is_last_visible && end < total {
            '↓'
        } else {
            ' '
        };
        if is_selected {
            lines.push(Line::from(vec![
                Span::raw(format!("{} ", prefix_char)),
                Span::styled(b.name.clone(), Style::default().fg(Color::Black).bg(Color::Cyan).add_modifier(Modifier::BOLD)),
            ]));
        } else {
            let prefix = if prefix_char == ' ' { "  ".to_string() } else { format!("{} ", prefix_char) };
            lines.push(Line::from(Span::styled(format!("{}{}", prefix, b.name), Style::default().fg(Color::White))));
        }
    }
    lines.push(Line::from(Span::styled("  ↑↓: select  Enter: jump  Esc: cancel", Style::default().fg(Color::DarkGray))));
    let height = (lines.len() as u16) + 2;
    (height, lines)
}

