// ---------- event handling ----------
fn handle_key(app: &mut App, key: KeyEvent) -> bool {
    // return true to quit
    if key.kind != KeyEventKind::Press {
        return false;
    }
    // Error takes precedence
    if app.error.is_some() {
        match key.code {
            KeyCode::Esc | KeyCode::Enter => { app.error = None; }
            KeyCode::Char('q') => { app.error = None; }
            _ => {}
        }
        return false;
    }
    match app.mode {
        Mode::Help => {
            match key.code {
                KeyCode::Esc => app.mode = Mode::Normal,
                KeyCode::Char('q') => app.mode = Mode::Normal,
                KeyCode::Char('?') => app.mode = Mode::Normal,
                _ => {}
            }
            false
        }
        Mode::BranchInput => {
            match key.code {
                KeyCode::Esc => { app.mode = Mode::Normal; app.input.clear(); }
                KeyCode::Enter => { app.do_create_branch(); }
                KeyCode::Backspace => {
                    if app.input.is_empty() {
                        app.mode = Mode::Normal;
                    } else {
                        app.input.pop();
                    }
                }
                KeyCode::Char(c) => { app.input.push(c); }
                _ => {}
            }
            false
        }
        Mode::DeleteConfirm => {
            match key.code {
                KeyCode::Char('y') | KeyCode::Enter => { app.do_delete_branch(); }
                KeyCode::Char('n') | KeyCode::Esc => { app.mode = Mode::Normal; app.pending_delete = None; }
                _ => {}
            }
            false
        }
        Mode::Search => {
            match key.code {
                KeyCode::Esc => {
                    // restore saved selection
                    app.selected = app.search_saved_selected;
                    app.selected_branch_index = app.search_saved_branch_index;
                    app.list_state.select(if app.data.rows.is_empty() { None } else { Some(app.selected.min(app.data.rows.len() - 1)) });
                    app.mode = Mode::Normal;
                    app.start_file_stats_for_selection();
                }
                KeyCode::Enter => {
                    app.mode = Mode::Normal;
                }
                KeyCode::Backspace => {
                    if app.search_query.is_empty() {
                        app.selected = app.search_saved_selected;
                        app.selected_branch_index = app.search_saved_branch_index;
                        app.list_state.select(if app.data.rows.is_empty() { None } else { Some(app.selected.min(app.data.rows.len() - 1)) });
                        app.mode = Mode::Normal;
                        app.start_file_stats_for_selection();
                    } else {
                        app.search_query.pop();
                        app.update_search_results();
                    }
                }
                KeyCode::Up => { app.search_move(-1); }
                KeyCode::Down => { app.search_move(1); }
                KeyCode::Char('j') if key.modifiers.contains(KeyModifiers::CONTROL) => { app.search_move(1); }
                KeyCode::Char('k') if key.modifiers.contains(KeyModifiers::CONTROL) => { app.search_move(-1); }
                KeyCode::Char(c) => {
                    app.search_query.push(c);
                    app.update_search_results();
                }
                _ => {}
            }
            false
        }
        Mode::Normal => {
            if key.modifiers.contains(KeyModifiers::CONTROL) {
                match key.code {
                    KeyCode::Char('d') => app.move_by(10),
                    KeyCode::Char('u') => app.move_by(-10),
                    _ => {}
                }
                return false;
            }
            match key.code {
                KeyCode::Char('q') | KeyCode::Esc => return true,
                KeyCode::Char('j') | KeyCode::Down => app.move_by(1),
                KeyCode::Char('k') | KeyCode::Up => app.move_by(-1),
                KeyCode::Char('h') | KeyCode::Left => {
                    if app.selected_branch_index > 0 { app.selected_branch_index -= 1; }
                }
                KeyCode::Char('l') | KeyCode::Right => {
                    if let Some(branches) = app.selected_branches() {
                        if !branches.is_empty() && app.selected_branch_index + 1 < branches.len() {
                            app.selected_branch_index += 1;
                        }
                    }
                }
                KeyCode::Char('g') | KeyCode::Home => app.move_to(0),
                KeyCode::Char('G') | KeyCode::End => {
                    if !app.data.rows.is_empty() { let idx = app.data.rows.len() - 1; app.move_to(idx); }
                }
                KeyCode::Char('@') => app.jump_to_head(),
                KeyCode::Char(']') | KeyCode::Tab => app.jump_next_branch(),
                KeyCode::Char('[') | KeyCode::BackTab => app.jump_prev_branch(),
                KeyCode::Enter => app.do_checkout(),
                KeyCode::Char('b') => { app.mode = Mode::BranchInput; app.input.clear(); }
                KeyCode::Char('d') => {
                    if let Some(branch) = app.selected_branch().cloned() {
                        if !branch.is_remote && !branch.is_head {
                            app.pending_delete = Some(branch.name.clone());
                            app.mode = Mode::DeleteConfirm;
                        }
                    }
                }
                KeyCode::Char('f') => {
                    app.last_fetch = Instant::now();
                    app.start_fetch(true);
                }
                KeyCode::Char('R') => {
                    app.refresh();
                }
                KeyCode::Char('/') => {
                    app.mode = Mode::Search;
                    app.search_query.clear();
                    app.search_results.clear();
                    app.search_index = 0;
                    app.search_saved_selected = app.selected;
                    app.search_saved_branch_index = app.selected_branch_index;
                }
                KeyCode::Char('?') => { app.mode = Mode::Help; }
                _ => {}
            }
            false
        }
    }
}

fn main() -> Result<()> {
    let mut cmd = Command::new("keifu")
        .version("0.2.3")
        .about("A TUI tool to visualize Git commit graphs with branch genealogy");
    let _matches = cmd.clone().get_matches();
    // clap handles help/version and errors before this point.
    let config = Config::load();
    let repo = Repository::discover(".").context("Git repository not found. Please run inside a Git repository.")?;
    let mut app = App::new(config, repo);
    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;
    let res = run_app(&mut terminal, &mut app);
    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;
    res
}

fn run_app<B: ratatui::backend::Backend>(terminal: &mut Terminal<B>, app: &mut App) -> Result<()> {
    loop {
        app.poll_async();
        terminal.draw(|f| draw(f, app))?;
        if event::poll(Duration::from_millis(100))? {
            if let Event::Key(key) = event::read()? {
                if handle_key(app, key) {
                    break;
                }
            }
        }
    }
    Ok(())
}
