fn lane_color(col: usize) -> Color {
    if col == 0 {
        Color::LightBlue
    } else {
        const COLORS: [Color; 9] = [
            Color::Green,
            Color::Magenta,
            Color::Yellow,
            Color::Red,
            Color::LightCyan,
            Color::LightGreen,
            Color::LightMagenta,
            Color::LightYellow,
            Color::LightRed,
        ];
        COLORS[(col - 1) % COLORS.len()]
    }
}
fn str_width(s: &str) -> usize {
    UnicodeWidthStr::width(s)
}
fn truncate_to_width(s: &str, max_width: usize) -> String {
    if str_width(s) <= max_width {
        return s.to_string();
    }
    let mut out = String::new();
    let mut w = 0usize;
    for g in s.graphemes(true) {
        let gw = UnicodeWidthStr::width(g);
        if w + gw > max_width {
            break;
        }
        out.push_str(g);
        w += gw;
    }
    out
}
