fn load_branches(repo: &Repository) -> Vec<BranchEntry> {
    let mut locals: Vec<BranchEntry> = Vec::new();
    let mut remotes: Vec<BranchEntry> = Vec::new();
    if let Ok(mut iter) = repo.branches(None) {
        for item in iter.by_ref() {
            let Ok((branch, branch_type)) = item else { continue };
            let target = match branch.get().target() {
                Some(t) => t,
                None => continue,
            };
            // Only keep branches pointing at commits
            if repo.find_commit(target).is_err() {
                // still keep? original likely keeps target; revwalk push will fail.
                // Keep it to match label behavior for non-commit refs is unlikely.
                // But to avoid weird rows, keep entry.
            }
            let name = match branch.name() {
                Ok(Some(n)) => n.to_string(),
                _ => {
                    // fallback to shorthand lossy
                    branch.get().shorthand().unwrap_or("").to_string()
                }
            };
            if name.is_empty() {
                continue;
            }
            // skip remote HEAD symbolic-ish entries named */HEAD where prefix has no other slash? 
            // Original at least skips origin/HEAD (target through symbolic gives Some in git2? get().target follows? may be Some)
            // We skip any remote branch whose name, stripped of first component, is exactly HEAD.
            let is_remote = branch_type == BranchType::Remote;
            if is_remote {
                if let Some((_, rest)) = name.split_once('/') {
                    if rest == "HEAD" {
                        continue;
                    }
                }
            }
            let is_head = branch.is_head();
            let entry = BranchEntry { name, target, is_remote, is_head, paired_remote: None };
            if is_remote { remotes.push(entry); } else { locals.push(entry); }
        }
    }
    // sort locals/remotes by name initially
    locals.sort_by(|a, b| a.name.cmp(&b.name));
    remotes.sort_by(|a, b| a.name.cmp(&b.name));
    let mut entries: Vec<BranchEntry> = locals;
    for remote in remotes {
        let (remote_name, local_name) = match remote.name.split_once('/') {
            Some((r, rest)) => (r.to_string(), rest.to_string()),
            None => (String::new(), remote.name.clone()),
        };
        let mut paired = false;
        for e in entries.iter_mut() {
            if !e.is_remote && e.name == local_name && e.target == remote.target && e.paired_remote.is_none() {
                e.paired_remote = Some(remote_name.clone());
                paired = true;
                break;
            }
        }
        if !paired {
            entries.push(remote);
        }
    }
    entries.sort_by(|a, b| {
        b.is_head.cmp(&a.is_head).then_with(|| a.name.cmp(&b.name))
    });
    entries
}

fn load_commits(repo: &Repository, branches: &[BranchEntry]) -> Vec<CommitInfo> {
    let mut commits = Vec::new();
    let Ok(mut walk) = repo.revwalk() else { return commits };
    let _ = walk.set_sorting(Sort::TOPOLOGICAL | Sort::TIME);
    for b in branches {
        let _ = walk.push(b.target);
    }
    for oid_res in walk.take(500) {
        let Ok(oid) = oid_res else { continue };
        let Ok(commit) = repo.find_commit(oid) else { continue };
        let author = commit.author();
        let message = commit.message().unwrap_or("").to_string();
        let summary = message.lines().next().unwrap_or("").to_string();
        commits.push(CommitInfo {
            id: oid,
            parents: commit.parent_ids().collect(),
            author_name: author.name().unwrap_or("").to_string(),
            author_email: author.email().unwrap_or("").to_string(),
            time: commit.time().seconds(),
            message,
            summary,
        });
    }
    commits
}

fn build_graph(commits: &[CommitInfo]) -> (Vec<GraphRow>, usize) {
    // lanes: each slot expects an oid
    let mut lanes: Vec<Option<Oid>> = Vec::new();
    let mut rows: Vec<GraphRow> = Vec::new();
    let mut max_lanes: usize = 0;
    fn alloc_lane(lanes: &mut Vec<Option<Oid>>) -> usize {
        if let Some(i) = lanes.iter().position(|l| l.is_none()) {
            i
        } else {
            lanes.push(None);
            lanes.len() - 1
        }
    }
    for (ci, commit) in commits.iter().enumerate() {
        let matching: Vec<usize> = lanes
            .iter()
            .enumerate()
            .filter_map(|(i, l)| if *l == Some(commit.id) { Some(i) } else { None })
            .collect();
        let column = if matching.is_empty() {
            alloc_lane(&mut lanes)
        } else {
            matching[0]
        };
        max_lanes = max_lanes.max(lanes.len());
        // connector row for multiple matching lanes
        if matching.len() > 1 {
            let merges: Vec<usize> = matching[1..].to_vec();
            let cells = build_connector_cells(&lanes, column, &merges);
            rows.push(GraphRow { kind: RowKind::Connector, cells, column });
            for &m in &merges {
                lanes[m] = None;
            }
        }
        // Determine additional parent lanes
        // lanes snapshot before updating
        let lanes_before = lanes.clone();
        let mut merge_edges: Vec<usize> = Vec::new(); // target lane indices for parents[1..]
        let mut new_lane_for_parent: HashMap<Oid, usize> = HashMap::new();
        for parent in commit.parents.iter().skip(1) {
            // existing lane (other than column) expecting parent?
            let existing = lanes_before
                .iter()
                .enumerate()
                .find(|(i, l)| *i != column && **l == Some(*parent))
                .map(|(i, _)| i);
            let target_lane = if let Some(i) = existing {
                i
            } else if let Some(&i) = new_lane_for_parent.get(parent) {
                i
            } else {
                // allocate in working lanes (so successive allocations differ)
                // We need to allocate based on current lanes state including prior allocations for this commit.
                // Use a provisional allocation on `lanes` but we haven't updated primary yet; lanes[column] still expects commit (or none), so alloc won't reuse column if it's Some(commit) or if newly allocated it is None!
                // To prevent reusing column when newly allocated, mark it temporarily.
                if lanes[column].is_none() {
                    lanes[column] = Some(commit.id);
                }
                let i = alloc_lane(&mut lanes);
                lanes[i] = Some(*parent);
                new_lane_for_parent.insert(*parent, i);
                i
            };
            merge_edges.push(target_lane);
        }
        max_lanes = max_lanes.max(lanes.len());
        // build commit row cells
        let width_slots = lanes.len().max(max_lanes).max(column + 1);
        let cells = build_commit_cells(&lanes_before, width_slots, column, commit, &merge_edges, &new_lane_for_parent);
        rows.push(GraphRow { kind: RowKind::Commit(ci), cells, column });
        // update lanes expectations
        if commit.parents.is_empty() {
            lanes[column] = None;
        } else {
            lanes[column] = Some(commit.parents[0]);
            // additional parents: ensure lanes[target] = parent (existing already)
            for (idx, parent) in commit.parents.iter().skip(1).enumerate() {
                let tl = merge_edges[idx];
                if tl >= lanes.len() { lanes.resize(tl + 1, None); }
                lanes[tl] = Some(*parent);
            }
        }
        max_lanes = max_lanes.max(lanes.len());
    }
    // pad all rows cells to max_lanes*2
    let target_len = max_lanes * 2;
    for row in rows.iter_mut() {
        while row.cells.len() < target_len {
            row.cells.push(GraphCell { ch: ' ', color: None });
        }
        row.cells.truncate(target_len.max(row.cells.len().min(target_len)));
        if row.cells.len() < target_len {
            while row.cells.len() < target_len { row.cells.push(GraphCell{ch:' ',color:None}); }
        }
    }
    (rows, max_lanes)
}

fn build_connector_cells(lanes: &[Option<Oid>], to: usize, merges: &[usize]) -> Vec<GraphCell> {
    let slots = lanes.len();
    let mut cells: Vec<GraphCell> = vec![GraphCell { ch: ' ', color: None }; slots * 2];
    // initial verticals
    for i in 0..slots {
        if lanes[i].is_some() {
            cells[i * 2] = GraphCell { ch: '│', color: Some(lane_color(i)) };
        }
    }
    let mut sorted = merges.to_vec();
    sorted.sort_unstable();
    for &from in &sorted {
        let src_color = lane_color(from);
        if from > to {
            cells[to * 2] = GraphCell { ch: '├', color: Some(lane_color(to)) };
            for x in (to * 2 + 1)..(from * 2) {
                if x % 2 == 0 {
                    let lane = x / 2;
                    if sorted.contains(&lane) {
                        cells[x] = GraphCell { ch: '┴', color: Some(lane_color(lane)) };
                    } else if lanes.get(lane).map(|l| l.is_some()).unwrap_or(false) {
                        cells[x] = GraphCell { ch: '┼', color: Some(lane_color(lane)) };
                    } else {
                        cells[x] = GraphCell { ch: '─', color: Some(src_color) };
                    }
                } else {
                    cells[x] = GraphCell { ch: '─', color: Some(src_color) };
                }
            }
            cells[from * 2] = GraphCell { ch: '╯', color: Some(src_color) };
        } else if from < to {
            // not expected since to is leftmost matching, but handle symmetric
            cells[to * 2] = GraphCell { ch: '┤', color: Some(lane_color(to)) };
            for x in (from * 2 + 1)..(to * 2) {
                if x % 2 == 0 {
                    let lane = x / 2;
                    if sorted.contains(&lane) {
                        cells[x] = GraphCell { ch: '┴', color: Some(lane_color(lane)) };
                    } else if lanes.get(lane).map(|l| l.is_some()).unwrap_or(false) {
                        cells[x] = GraphCell { ch: '┼', color: Some(lane_color(lane)) };
                    } else {
                        cells[x] = GraphCell { ch: '─', color: Some(src_color) };
                    }
                } else {
                    cells[x] = GraphCell { ch: '─', color: Some(src_color) };
                }
            }
            cells[from * 2] = GraphCell { ch: '╰', color: Some(src_color) };
        }
    }
    cells
}

fn build_commit_cells(
    lanes_before: &[Option<Oid>],
    width_slots: usize,
    column: usize,
    commit: &CommitInfo,
    merge_edges: &[usize],
    new_lane_for_parent: &HashMap<Oid, usize>,
) -> Vec<GraphCell> {
    let mut cells: Vec<GraphCell> = vec![GraphCell { ch: ' ', color: None }; width_slots * 2];
    for i in 0..width_slots {
        let active = if i < lanes_before.len() { lanes_before[i].is_some() } else { false };
        if i == column {
            // node char decided in UI based on head; store placeholder ● here, UI may replace.
            cells[i * 2] = GraphCell { ch: '●', color: Some(lane_color(i)) };
        } else if active {
            cells[i * 2] = GraphCell { ch: '│', color: Some(lane_color(i)) };
        }
    }
    // Draw merge edges in order given. Draw segments between successive anchor points to mimic original octopus behavior.
    // Anchors: start at column, then each target in order; but for targets to the left, draw individually.
    // We process each edge from column to target, but avoid overwriting a previously drawn endpoint's char/color for intermediate positions
    // except for dashes beyond previous endpoint.
    let mut drawn_up_to: Option<usize> = None; // for rightward edges, max x already drawn
    for (idx, &target) in merge_edges.iter().enumerate() {
        let parent = commit.parents[idx + 1];
        let is_new = new_lane_for_parent.get(&parent).map(|&i| i == target).unwrap_or(false);
        let tcolor = lane_color(target);
        if target > column {
            let start_x = column * 2;
            let end_x = target * 2;
            for x in (start_x + 1)..end_x {
                // skip positions already drawn as part of previous rightward edge, except we need to draw dashes after previous endpoint
                if let Some(up) = drawn_up_to {
                    if x <= up { continue; }
                }
                if x % 2 == 0 {
                    let lane = x / 2;
                    let was_active = lane < lanes_before.len() && lanes_before[lane].is_some();
                    if was_active && lane != column {
                        // crossing a vertical lane
                        cells[x] = GraphCell { ch: '┼', color: Some(lane_color(lane)) };
                    } else {
                        cells[x] = GraphCell { ch: '─', color: Some(tcolor) };
                    }
                } else {
                    cells[x] = GraphCell { ch: '─', color: Some(tcolor) };
                }
            }
            // endpoint
            if is_new {
                cells[end_x] = GraphCell { ch: '╮', color: Some(tcolor) };
            } else {
                cells[end_x] = GraphCell { ch: '┤', color: Some(tcolor) };
            }
            drawn_up_to = Some(end_x);
        } else if target < column {
            let start_x = target * 2;
            let end_x = column * 2;
            for x in (start_x + 1)..end_x {
                if x % 2 == 0 {
                    let lane = x / 2;
                    let was_active = lane < lanes_before.len() && lanes_before[lane].is_some();
                    if was_active {
                        cells[x] = GraphCell { ch: '┼', color: Some(lane_color(lane)) };
                    } else {
                        cells[x] = GraphCell { ch: '─', color: Some(tcolor) };
                    }
                } else {
                    cells[x] = GraphCell { ch: '─', color: Some(tcolor) };
                }
            }
            if is_new {
                cells[start_x] = GraphCell { ch: '╭', color: Some(tcolor) };
            } else {
                cells[start_x] = GraphCell { ch: '├', color: Some(tcolor) };
            }
        }
    }
    cells
}

fn status_char_and_color(status: git2::Delta) -> (char, Color) {
    match status {
        git2::Delta::Added => ('A', Color::Green),
        git2::Delta::Deleted => ('D', Color::Red),
        git2::Delta::Modified => ('M', Color::Yellow),
        git2::Delta::Renamed => ('R', Color::Yellow),
        git2::Delta::Copied => ('C', Color::Green),
        git2::Delta::Typechange => ('T', Color::Yellow),
        _ => ('?', Color::White),
    }
}

fn diff_to_stats(diff: &git2::Diff, cap: usize, count_override: Option<usize>) -> FileStats {
    let total_files = count_override.unwrap_or_else(|| diff.deltas().len());
    let mut files = Vec::new();
    let mut total_insertions = 0usize;
    let mut total_deletions = 0usize;
    for (i, delta) in diff.deltas().enumerate().take(cap) {
        let (status, _c) = status_char_and_color(delta.status());
        let path = delta
            .new_file()
            .path()
            .or_else(|| delta.old_file().path())
            .map(|p| p.to_string_lossy().to_string())
            .unwrap_or_default();
        let (ins, del) = match git2::Patch::from_diff(diff, i) {
            Ok(Some(patch)) => match patch.line_stats() {
                Ok((_, a, d)) => (a, d),
                Err(_) => (0, 0),
            },
            _ => (0, 0),
        };
        total_insertions += ins;
        total_deletions += del;
        files.push(FileStat { path, status, insertions: ins, deletions: del });
    }
    FileStats { files_changed: total_files, total_insertions, total_deletions, files }
}

fn get_commit_file_stats(repo_path: &Path, oid: Oid) -> Option<FileStats> {
    let repo = Repository::open(repo_path).ok()?;
    let commit = repo.find_commit(oid).ok()?;
    let tree = commit.tree().ok()?;
    let parent_tree = if commit.parent_count() > 0 {
        commit.parent(0).and_then(|p| p.tree()).ok()
    } else { None };
    let mut opts = DiffOptions::new();
    opts.include_typechange(true);
    let diff = repo.diff_tree_to_tree(parent_tree.as_ref(), Some(&tree), Some(&mut opts)).ok()?;
    Some(diff_to_stats(&diff, 50, None))
}

fn get_uncommitted(repo: &Repository) -> Option<(usize, FileStats)> {
    // Need HEAD tree; if unborn, return None
    let head_tree = repo.head().ok()?.peel_to_tree().ok()?;
    let index = repo.index().ok()?;
    let mut opts = DiffOptions::new();
    opts.include_typechange(true);
    let staged = repo.diff_tree_to_index(Some(&head_tree), Some(&index), Some(&mut opts)).ok()?;
    let mut opts2 = DiffOptions::new();
    opts2.include_typechange(true);
    let unstaged = repo.diff_index_to_workdir(Some(&index), Some(&mut opts2)).ok()?;
    // unique path count
    let mut unique_paths: HashSet<String> = HashSet::new();
    for diff in [&staged, &unstaged] {
        for delta in diff.deltas() {
            let path = delta.new_file().path().or_else(|| delta.old_file().path()).map(|p| p.to_string_lossy().to_string()).unwrap_or_default();
            unique_paths.insert(path);
        }
    }
    let count = unique_paths.len();
    if count == 0 {
        return Some((0, FileStats { files_changed: 0, total_insertions: 0, total_deletions: 0, files: vec![] }));
    }
    // combined files list, with totals counting duplicate path patches as long as path was included (or cap not reached conceptually)
    let mut files: Vec<FileStat> = Vec::new();
    let mut seen_included: HashSet<String> = HashSet::new();
    let mut total_insertions = 0usize;
    let mut total_deletions = 0usize;
    for diff in [&staged, &unstaged] {
        for (i, delta) in diff.deltas().enumerate() {
            let (status, _) = status_char_and_color(delta.status());
            let path = delta.new_file().path().or_else(|| delta.old_file().path()).map(|p| p.to_string_lossy().to_string()).unwrap_or_default();
            let (ins, del) = match git2::Patch::from_diff(diff, i) {
                Ok(Some(patch)) => match patch.line_stats() { Ok((_, a, d)) => (a, d), Err(_) => (0, 0) },
                _ => (0, 0),
            };
            if seen_included.contains(&path) {
                total_insertions += ins;
                total_deletions += del;
            } else if files.len() < 50 {
                total_insertions += ins;
                total_deletions += del;
                seen_included.insert(path.clone());
                files.push(FileStat { path, status, insertions: ins, deletions: del });
            } else {
                // beyond cap, new path not counted in totals (matching observed 60-file staged case)
            }
        }
    }
    let stats = FileStats { files_changed: files.len(), total_insertions, total_deletions, files };
    Some((count, stats))
}

fn load_repo_data(repo: Repository) -> RepoData {
    let repo_path = repo.workdir().map(|p| p.to_path_buf()).unwrap_or_else(|| repo.path().to_path_buf());
    let repo_name = repo_path.file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or_default();
    let current_branch = repo.head().ok().and_then(|h| h.shorthand().map(|s| s.to_string()));
    let branches = load_branches(&repo);
    let commits = load_commits(&repo, &branches);
    let mut commit_branches: Vec<Vec<BranchEntry>> = Vec::with_capacity(commits.len());
    for c in &commits {
        let mut v: Vec<BranchEntry> = branches.iter().filter(|b| b.target == c.id).cloned().collect();
        v.sort_by(|a, b| b.is_head.cmp(&a.is_head).then_with(|| a.name.cmp(&b.name)));
        commit_branches.push(v);
    }
    let (mut rows, max_lanes) = build_graph(&commits);
    let (uncommitted_count, uncommitted_stats) = match get_uncommitted(&repo) {
        Some((cnt, stats)) if cnt > 0 => (cnt, Some(stats)),
        _ => (0, None),
    };
    if uncommitted_count > 0 {
        let mut cells: Vec<GraphCell> = vec![GraphCell { ch: ' ', color: None }; (max_lanes.max(1)) * 2];
        if !cells.is_empty() {
            cells[0] = GraphCell { ch: '●', color: Some(Color::DarkGray) };
        }
        rows.insert(0, GraphRow { kind: RowKind::Uncommitted, cells, column: 0 });
    }
    RepoData { repo_path, repo_name, current_branch, branches, commits, commit_branches, rows, max_lanes, uncommitted_count, uncommitted_stats }
}

// ---------- app ----------
struct App {
    config: Config,
    data: RepoData,
    repo_path: PathBuf,
    selected: usize,
    selected_branch_index: usize,
    mode: Mode,
    input: String,
    pending_delete: Option<String>,
    search_query: String,
    search_results: Vec<BranchEntry>,
    search_index: usize,
    search_saved_selected: usize,
    search_saved_branch_index: usize,
    error: Option<String>,
    message: Option<String>,
    message_time: Option<Instant>,
    last_refresh: Instant,
    last_fetch: Instant,
    list_state: ListState,
    file_stats: Option<FileStats>,
    file_stats_loading: bool,
    file_stats_rx: Option<mpsc::Receiver<Option<FileStats>>>,
    fetch_rx: Option<mpsc::Receiver<std::result::Result<(), String>>>,
    fetch_manual: bool,
    fetching: bool,
}

impl App {
    fn new(config: Config, repo: Repository) -> Self {
        let data = load_repo_data(repo);
        let repo_path = data.repo_path.clone();
        let mut app = Self {
            config,
            data,
            repo_path,
            selected: 0,
            selected_branch_index: 0,
            mode: Mode::Normal,
            input: String::new(),
            pending_delete: None,
            search_query: String::new(),
            search_results: Vec::new(),
            search_index: 0,
            search_saved_selected: 0,
            search_saved_branch_index: 0,
            error: None,
            message: None,
            message_time: None,
            last_refresh: Instant::now(),
            last_fetch: Instant::now(),
            list_state: ListState::default(),
            file_stats: None,
            file_stats_loading: false,
            file_stats_rx: None,
            fetch_rx: None,
            fetch_manual: false,
            fetching: false,
        };
        app.list_state.select(if app.data.rows.is_empty() { None } else { Some(0) });
        app.start_file_stats_for_selection();
        app
    }
    fn set_message(&mut self, msg: &str) {
        self.message = Some(msg.to_string());
        self.message_time = Some(Instant::now());
    }
    fn set_error(&mut self, msg: String) {
        self.error = Some(msg);
    }
    fn selected_row(&self) -> Option<&GraphRow> {
        self.data.rows.get(self.selected)
    }
    fn selected_commit_idx(&self) -> Option<usize> {
        match self.selected_row()?.kind {
            RowKind::Commit(ci) => Some(ci),
            _ => None,
        }
    }
    fn selected_commit(&self) -> Option<&CommitInfo> {
        let ci = self.selected_commit_idx()?;
        self.data.commits.get(ci)
    }
    fn selected_branches(&self) -> Option<&Vec<BranchEntry>> {
        let ci = self.selected_commit_idx()?;
        self.data.commit_branches.get(ci)
    }
    fn selected_branch(&self) -> Option<&BranchEntry> {
        let branches = self.selected_branches()?;
        if branches.is_empty() { return None; }
        let idx = self.selected_branch_index.min(branches.len() - 1);
        Some(&branches[idx])
    }
    fn clamp_selection(&mut self) {
        if self.data.rows.is_empty() {
            self.selected = 0;
            self.list_state.select(None);
        } else {
            if self.selected >= self.data.rows.len() {
                self.selected = self.data.rows.len() - 1;
            }
            self.list_state.select(Some(self.selected));
        }
        if let Some(branches) = self.selected_branches() {
            if branches.is_empty() {
                self.selected_branch_index = 0;
            } else if self.selected_branch_index >= branches.len() {
                // Keep index as-is? Original clamps display; but for operations clamp logically.
                // We clamp to avoid out-of-range surprises, except search bug cases not reproduced.
                self.selected_branch_index = branches.len() - 1;
            }
        }
    }
    fn start_file_stats_for_selection(&mut self) {
        if let Some(ci) = self.selected_commit_idx() {
            let oid = self.data.commits[ci].id;
            let path = self.repo_path.clone();
            let (tx, rx) = mpsc::channel();
            self.file_stats = None;
            self.file_stats_loading = true;
            self.file_stats_rx = Some(rx);
            std::thread::spawn(move || {
                let stats = get_commit_file_stats(&path, oid);
                let _ = tx.send(stats);
            });
        }
        // For connector/uncommitted, do not clear existing file_stats, do not start load.
    }
    fn move_to(&mut self, idx: usize) {
        if self.data.rows.is_empty() { return; }
        let new_idx = idx.min(self.data.rows.len() - 1);
        if new_idx != self.selected {
            self.selected = new_idx;
            self.selected_branch_index = 0;
            self.list_state.select(Some(self.selected));
            self.start_file_stats_for_selection();
        }
    }
    fn move_by(&mut self, delta: i64) {
        if self.data.rows.is_empty() { return; }
        let len = self.data.rows.len() as i64;
        let new_idx = (self.selected as i64 + delta).clamp(0, len - 1) as usize;
        self.move_to(new_idx);
    }
    fn branch_row_indices(&self) -> Vec<usize> {
        let mut v = Vec::new();
        for (i, row) in self.data.rows.iter().enumerate() {
            if let RowKind::Commit(ci) = row.kind {
                if self.data.commit_branches.get(ci).map(|b| !b.is_empty()).unwrap_or(false) {
                    v.push(i);
                }
            }
        }
        v
    }
    fn jump_next_branch(&mut self) {
        let indices = self.branch_row_indices();
        if indices.is_empty() { return; }
        if let Some(pos) = indices.iter().position(|&i| i == self.selected) {
            if pos + 1 < indices.len() {
                self.move_to(indices[pos + 1]);
            }
        } else {
            self.move_to(indices[0]);
        }
    }
    fn jump_prev_branch(&mut self) {
        let indices = self.branch_row_indices();
        if indices.is_empty() { return; }
        if let Some(pos) = indices.iter().position(|&i| i == self.selected) {
            if pos > 0 {
                self.move_to(indices[pos - 1]);
            }
        } else {
            self.move_to(indices[indices.len() - 1]);
        }
    }
    fn jump_to_head(&mut self) {
        for (i, row) in self.data.rows.iter().enumerate() {
            if let RowKind::Commit(ci) = row.kind {
                if let Some(branches) = self.data.commit_branches.get(ci) {
                    if branches.iter().any(|b| b.is_head) {
                        self.move_to(i);
                        return;
                    }
                }
            }
        }
    }
    fn refresh(&mut self) {
        if let Ok(repo) = Repository::open(&self.repo_path) {
            self.data = load_repo_data(repo);
            self.clamp_selection();
            self.start_file_stats_for_selection();
        } else if let Ok(repo) = Repository::discover(&self.repo_path) {
            self.data = load_repo_data(repo);
            self.clamp_selection();
            self.start_file_stats_for_selection();
        }
    }
    fn open_repo(&self) -> std::result::Result<Repository, git2::Error> {
        Repository::open(&self.repo_path).or_else(|_| Repository::discover(&self.repo_path))
    }
    fn do_checkout(&mut self) {
        let Some(ci) = self.selected_commit_idx() else { return };
        let oid = self.data.commits[ci].id;
        let branch_opt = self.selected_branch().cloned();
        let result: std::result::Result<(), git2::Error> = (|| {
            let repo = self.open_repo()?;
            if let Some(branch) = branch_opt {
                if branch.is_remote {
                    checkout_remote(&repo, &branch)?;
                } else {
                    checkout_local(&repo, &branch.name)?;
                }
            } else {
                let obj = repo.find_object(oid, None)?;
                repo.checkout_tree(&obj, None)?;
                repo.set_head_detached(oid)?;
            }
            Ok(())
        })();
        match result {
            Ok(()) => self.refresh(),
            Err(e) => self.set_error(e.to_string()),
        }
    }
    fn do_create_branch(&mut self) {
        let name = self.input.trim().to_string();
        self.mode = Mode::Normal;
        self.input.clear();
        if name.is_empty() { return; }
        let Some(ci) = self.selected_commit_idx() else { return };
        let oid = self.data.commits[ci].id;
        let result: std::result::Result<(), git2::Error> = (|| {
            let repo = self.open_repo()?;
            let commit = repo.find_commit(oid)?;
            repo.branch(&name, &commit, false)?;
            Ok(())
        })();
        match result {
            Ok(()) => self.refresh(),
            Err(_) => self.set_error(format!("Failed to create branch '{}'", name)),
        }
    }
    fn do_delete_branch(&mut self) {
        let Some(name) = self.pending_delete.take() else { self.mode = Mode::Normal; return };
        self.mode = Mode::Normal;
        let result: std::result::Result<(), git2::Error> = (|| {
            let repo = self.open_repo()?;
            let mut branch = repo.find_branch(&name, BranchType::Local)?;
            branch.delete()?;
            Ok(())
        })();
        match result {
            Ok(()) => self.refresh(),
            Err(e) => self.set_error(e.to_string()),
        }
    }
    fn start_fetch(&mut self, manual: bool) {
        if self.fetching { return; }
        self.fetching = true;
        self.fetch_manual = manual;
        self.set_message("Fetching from origin...");
        let (tx, rx) = mpsc::channel();
        self.fetch_rx = Some(rx);
        let path = self.repo_path.clone();
        std::thread::spawn(move || {
            let output = ProcCommand::new("git").args(["fetch", "origin"]).current_dir(&path).output();
            let res = match output {
                Ok(out) if out.status.success() => Ok(()),
                Ok(out) => {
                    let stderr = String::from_utf8_lossy(&out.stderr);
                    let cleaned: String = stderr.lines().collect();
                    Err(format!("git fetch failed: {}", cleaned))
                }
                Err(_) => Err("Failed to execute git fetch".to_string()),
            };
            let _ = tx.send(res);
        });
    }
    fn poll_async(&mut self) {
        if let Some(rx) = &self.file_stats_rx {
            if let Ok(stats) = rx.try_recv() {
                self.file_stats = stats;
                self.file_stats_loading = false;
                self.file_stats_rx = None;
            }
        }
        if let Some(rx) = &self.fetch_rx {
            if let Ok(res) = rx.try_recv() {
                self.fetching = false;
                self.fetch_rx = None;
                match res {
                    Ok(()) => {
                        // Original appears to keep message timestamp from Fetching start (approx). Keep existing message_time if present.
                        let old_time = self.message_time;
                        self.message = Some("Fetched from origin".to_string());
                        if old_time.is_some() {
                            self.message_time = old_time;
                        } else {
                            self.message_time = Some(Instant::now());
                        }
                        self.refresh();
                    }
                    Err(msg) => {
                        if self.fetch_manual {
                            self.set_error(msg);
                        } else {
                            // auto fetch errors are silent; clear fetching message
                            self.message = None;
                            self.message_time = None;
                        }
                    }
                }
            }
        }
        if let (Some(_), Some(t)) = (&self.message, self.message_time) {
            if t.elapsed() >= Duration::from_secs(5) {
                self.message = None;
                self.message_time = None;
            }
        }
        // auto refresh / fetch timers
        if self.config.refresh.auto_refresh && self.last_refresh.elapsed() >= Duration::from_secs(self.config.refresh.refresh_interval) {
            self.last_refresh = Instant::now();
            self.refresh();
        }
        if self.config.refresh.auto_fetch && self.last_fetch.elapsed() >= Duration::from_secs(self.config.refresh.fetch_interval) {
            self.last_fetch = Instant::now();
            // Only auto-fetch if origin exists (matches silent behavior for no-origin repos)
            let has_origin = self.open_repo().map(|r| r.find_remote("origin").is_ok()).unwrap_or(false);
            if has_origin {
                self.start_fetch(false);
            }
        }
    }
    fn update_search_results(&mut self) {
        self.search_results = fuzzy_search(&self.search_query, &self.data.branches);
        self.search_index = 0;
        if let Some(first) = self.search_results.first().cloned() {
            self.preview_branch(&first);
        }
    }
    fn preview_branch(&mut self, branch: &BranchEntry) {
        for (i, row) in self.data.rows.iter().enumerate() {
            if let RowKind::Commit(ci) = row.kind {
                if self.data.commits[ci].id == branch.target {
                    // set selection without using move_to's branch reset logic fully; we need set branch index after
                    let branch_idx = self.data.commit_branches[ci].iter().position(|b| b.name == branch.name).unwrap_or(0);
                    if self.selected != i {
                        self.selected = i;
                        self.list_state.select(Some(i));
                        self.start_file_stats_for_selection();
                    }
                    self.selected_branch_index = branch_idx;
                    return;
                }
            }
        }
    }
    fn search_move(&mut self, delta: i64) {
        if self.search_results.is_empty() { return; }
        let len = self.search_results.len() as i64;
        let mut idx = self.search_index as i64 + delta;
        if idx < 0 { idx = len - 1; }
        if idx >= len { idx = 0; }
        self.search_index = idx as usize;
        if let Some(b) = self.search_results.get(self.search_index).cloned() {
            self.preview_branch(&b);
        }
    }
}

fn checkout_local(repo: &Repository, name: &str) -> std::result::Result<(), git2::Error> {
    let branch = repo.find_branch(name, BranchType::Local)?;
    let target = branch.get().target().ok_or_else(|| git2::Error::from_str("branch target not found"))?;
    let obj = repo.find_object(target, None)?;
    repo.checkout_tree(&obj, None)?;
    let refname = branch.get().name().ok_or_else(|| git2::Error::from_str("branch ref not found"))?;
    repo.set_head(refname)?;
    Ok(())
}
fn checkout_remote(repo: &Repository, branch: &BranchEntry) -> std::result::Result<(), git2::Error> {
    let local_name = branch.name.split_once('/').map(|(_, rest)| rest).unwrap_or(&branch.name).to_string();
    let commit = repo.find_commit(branch.target)?;
    // create or update local branch first (as per docs behavior); upstream only on creation.
    match repo.find_branch(&local_name, BranchType::Local) {
        Ok(mut local) => {
            if local.get().target() != Some(branch.target) {
                // force update
                let _ = repo.branch(&local_name, &commit, true)?;
            }
        }
        Err(_) => {
            let mut local = repo.branch(&local_name, &commit, false)?;
            let _ = local.set_upstream(Some(&branch.name));
        }
    }
    let obj = repo.find_object(branch.target, None)?;
    repo.checkout_tree(&obj, None)?;
    repo.set_head(&format!("refs/heads/{}", local_name))?;
    Ok(())
}

// ---------- fuzzy search ----------
fn fuzzy_score(query: &str, target: &str) -> Option<i32> {
    if query.is_empty() { return None; }
    // Find subsequence (case-sensitive) with a scoring that rewards contiguous, start and boundary matches.
    // Use DP to choose best alignment (simple O(n*m) for branch names, sizes are small)
    let q: Vec<char> = query.chars().collect();
    let t: Vec<char> = target.chars().collect();
    // Quick subsequence check greedy
    {
        let mut qi = 0;
        for &c in &t {
            if qi < q.len() && c == q[qi] { qi += 1; }
        }
        if qi < q.len() { return None; }
    }
    // Bonus categories help approximate observed ordering
    let mut score: i32 = 0;
    if target.starts_with(query) {
        score += 100;
    } else if target.contains(query) {
        score += 50;
    }
    // Greedy alignment scoring
    let mut qi = 0usize;
    let mut prev_match_idx: Option<usize> = None;
    let mut first_match_idx: Option<usize> = None;
    let mut last_match_idx = 0usize;
    for (i, &c) in t.iter().enumerate() {
        if qi < q.len() && c == q[qi] {
            if first_match_idx.is_none() { first_match_idx = Some(i); }
            // boundary bonus
            let is_boundary = i == 0 || matches!(t[i - 1], '/' | '-' | '_' | '.') || (t[i - 1].is_lowercase() && c.is_uppercase());
            if is_boundary { score += 15; }
            if let Some(p) = prev_match_idx {
                if i == p + 1 { score += 10; } else { score -= (i - p - 1) as i32; }
            }
            score += 10;
            prev_match_idx = Some(i);
            last_match_idx = i;
            qi += 1;
            if qi >= q.len() { break; }
        }
    }
    if let Some(f) = first_match_idx {
        score -= f as i32 * 2;
        score -= (last_match_idx - f) as i32;
    }
    // slight preference for shorter names
    score -= (t.len() as i32) / 8;
    Some(score)
}
fn fuzzy_search(query: &str, branches: &[BranchEntry]) -> Vec<BranchEntry> {
    if query.is_empty() { return Vec::new(); }
    let mut scored: Vec<(i32, usize, BranchEntry)> = Vec::new();
    for (idx, b) in branches.iter().enumerate() {
        if let Some(s) = fuzzy_score(query, &b.name) {
            scored.push((s, idx, b.clone()));
        }
    }
    scored.sort_by(|a, b| b.0.cmp(&a.0).then_with(|| a.1.cmp(&b.1)));
    scored.into_iter().map(|(_, _, b)| b).collect()
}

// ---------- UI ----------
fn centered_rect(percent_x: u16, percent_y: u16, r: Rect) -> Rect {
    let popup_layout = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Percentage((100 - percent_y) / 2),
            Constraint::Percentage(percent_y),
            Constraint::Percentage((100 - percent_y) / 2),
        ])
        .split(r);
    Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage((100 - percent_x) / 2),
            Constraint::Percentage(percent_x),
            Constraint::Percentage((100 - percent_x) / 2),
        ])
        .split(popup_layout[1])[1]
}

fn branch_display_name(branch: &BranchEntry, total_branches: usize) -> String {
    if total_branches == 1 {
        if let Some(remote) = &branch.paired_remote {
            return format!("{} ↔ {}", branch.name, remote);
        }
    }
    branch.name.clone()
}

fn build_commit_line(app: &App, row_idx: usize, inner_width: u16) -> Line<'static> {
    let row = &app.data.rows[row_idx];
    let is_selected = row_idx == app.selected;
    let mut spans: Vec<Span<'static>> = Vec::new();
    spans.push(Span::raw(" "));
    // For commit rows, node char may need to be ◉ if head branch
    let is_head_commit = match row.kind {
        RowKind::Commit(ci) => app.data.commit_branches.get(ci).map(|bs| bs.iter().any(|b| b.is_head)).unwrap_or(false),
        _ => false,
    };
    for cell in &row.cells {
        let mut ch = cell.ch;
        if ch == '●' && is_head_commit {
            if let RowKind::Commit(_) = row.kind {
                // only replace the node cell (at row.column*2) - other ● are nodes too only one per row
                ch = '◉';
            }
        }
        let style = if let Some(color) = cell.color {
            Style::default().fg(color).add_modifier(Modifier::BOLD)
        } else {
            Style::default().add_modifier(Modifier::BOLD)
        };
        spans.push(Span::styled(ch.to_string(), style));
    }
    spans.push(Span::raw(" "));
    let graph_text_start = 1 + row.cells.len() + 1; // spaces + cells within inner (relative to inner left)
    match row.kind {
        RowKind::Connector => {
            // no text
            Line::from(spans)
        }
        RowKind::Uncommitted => {
            let text = format!("uncommitted changes ({})", app.data.uncommitted_count);
            spans.push(Span::styled(text, Style::default().fg(Color::White)));
            Line::from(spans)
        }
        RowKind::Commit(ci) => {
            let commit = &app.data.commits[ci];
            let branches = &app.data.commit_branches[ci];
            let mut label_text = String::new();
            let mut label_color = lane_color(row.column);
            if !branches.is_empty() {
                let bidx = if is_selected { app.selected_branch_index.min(branches.len() - 1) } else { 0 };
                let b = &branches[bidx];
                let disp = branch_display_name(b, branches.len());
                if branches.len() > 1 {
                    label_text = format!("[{}] +{}", disp, branches.len() - 1);
                } else {
                    label_text = format!("[{}]", disp);
                }
                label_color = lane_color(row.column);
                let lstyle = if is_selected {
                    Style::default().fg(Color::Black)
                } else {
                    Style::default().fg(label_color).add_modifier(Modifier::BOLD)
                };
                spans.push(Span::styled(label_text.clone(), lstyle));
                spans.push(Span::raw(" "));
            }
            // compute available width for message + columns
            let iw = inner_width as usize;
            // remaining after prefix (graph_text_start) and label
            let label_w = if label_text.is_empty() { 0 } else { str_width(&label_text) + 1 };
            let remaining = iw.saturating_sub(graph_text_start + label_w);
            let show_author = remaining >= 61;
            let show_date = remaining >= 72;
            let show_hash = remaining >= 81;
            let mut reserved = 0usize;
            if show_date { reserved += 11; }
            if show_author { reserved += 10; }
            if show_hash { reserved += 9; }
            if show_author { reserved += 1; } // trailing space
            let msg_width = remaining.saturating_sub(reserved);
            let msg = truncate_to_width(&commit.summary, msg_width);
            let msg_disp_w = str_width(&msg);
            let padded = if msg_disp_w < msg_width {
                format!("{}{}", msg, " ".repeat(msg_width - msg_disp_w))
            } else { msg };
            spans.push(Span::raw(padded));
            if show_date {
                spans.push(Span::raw(" "));
                spans.push(Span::styled(format_date(commit.time), Style::default().fg(Color::DarkGray)));
            }
            if show_author {
                spans.push(Span::raw("  "));
                let author_trunc = truncate_to_width(&commit.author_name, 8);
                // format pads based on char count (Rust {:<8} behavior equivalent for our purposes counts chars())
                let author_disp = format!("{:<8}", author_trunc);
                spans.push(Span::styled(author_disp, Style::default().fg(Color::Cyan)));
            }
            if show_hash {
                spans.push(Span::raw("  "));
                spans.push(Span::styled(short_oid(commit.id), Style::default().fg(Color::Yellow)));
            }
            if show_author {
                spans.push(Span::raw(" "));
            }
            Line::from(spans)
        }
    }
}

fn render_status_bar(frame: &mut Frame, app: &App, area: Rect) {
    // right mode label
    let mode_label: Option<String> = if app.error.is_some() {
        Some(" ERROR".to_string())
    } else {
        match app.mode {
            Mode::BranchInput | Mode::Search => Some(" INPUT".to_string()),
            Mode::DeleteConfirm => Some(" CONFIRM".to_string()),
            Mode::Help => Some(" HELP".to_string()),
            Mode::Normal => None,
        }
    };
    let label_w = mode_label.as_ref().map(|s| str_width(s) as u16).unwrap_or(0);
    let (left_area, right_area) = if label_w > 0 && area.width > label_w {
        let chunks = Layout::default().direction(Direction::Horizontal).constraints([Constraint::Min(0), Constraint::Length(label_w)]).split(area);
        (chunks[0], Some(chunks[1]))
    } else {
        (area, None)
    };
    let mut spans: Vec<Span> = Vec::new();
    spans.push(Span::styled(format!(" {} ", app.data.repo_name), Style::default().fg(Color::Black).bg(Color::Magenta).add_modifier(Modifier::BOLD)));
    spans.push(Span::raw(" "));
    if let Some(cb) = &app.data.current_branch {
        spans.push(Span::styled(format!(" {} ", cb), Style::default().fg(Color::Black).bg(Color::Green)));
        spans.push(Span::raw(" "));
    }
    if let Some(err) = &app.error {
        spans.push(Span::styled(format!(" {} ", err), Style::default().fg(Color::White).bg(Color::Red).add_modifier(Modifier::BOLD)));
        spans.push(Span::raw("  "));
        // key hint Esc/Enter close
        spans.push(Span::styled(" Esc/Enter ", Style::default().fg(Color::Black).bg(Color::Cyan).add_modifier(Modifier::BOLD)));
        spans.push(Span::styled("close", Style::default().fg(Color::White)));
    } else if let Some(msg) = &app.message {
        spans.push(Span::styled(format!(" {} ", msg), Style::default().fg(Color::Black).bg(Color::Cyan).add_modifier(Modifier::BOLD)));
    } else {
        let hints: Vec<(&str, &str)> = match app.mode {
            Mode::Normal => vec![("j/k", "move"), ("Enter", "checkout"), ("b", "branch"), ("f", "fetch"), ("?", "help"), ("q", "quit")],
            Mode::BranchInput | Mode::Search => vec![("Enter", "confirm"), ("Esc", "cancel")],
            Mode::DeleteConfirm => vec![("y", "yes"), ("n", "no")],
            Mode::Help => vec![("Esc/q", "close help")],
        };
        for (i, (k, desc)) in hints.iter().enumerate() {
            spans.push(Span::styled(format!(" {} ", k), Style::default().fg(Color::Black).bg(Color::Cyan).add_modifier(Modifier::BOLD)));
            if i + 1 < hints.len() {
                spans.push(Span::styled(format!("{} ", desc), Style::default().fg(Color::White)));
            } else {
                spans.push(Span::styled(desc.to_string(), Style::default().fg(Color::White)));
            }
        }
    }
    let para = Paragraph::new(Line::from(spans));
    frame.render_widget(para, left_area);
    if let (Some(label), Some(ra)) = (mode_label, right_area) {
        let p = Paragraph::new(Line::from(Span::styled(label, Style::default().fg(Color::Black).bg(Color::Yellow).add_modifier(Modifier::BOLD))));
        frame.render_widget(p, ra);
    }
}

fn render_commit_detail(frame: &mut Frame, app: &App, area: Rect) {
    let block = Block::default().title(" Commit Detail ").borders(Borders::ALL).border_style(Style::default().fg(Color::DarkGray));
    let inner = block.inner(area);
    frame.render_widget(block, area);
    if inner.width == 0 || inner.height == 0 { return; }
    let text: Text = match app.selected_row().map(|r| &r.kind) {
        Some(RowKind::Uncommitted) => {
            Text::from(vec![
                Line::from("Uncommitted Changes"),
                Line::from(""),
                Line::from(format!("{} files with changes", app.data.uncommitted_count)),
            ])
        }
        Some(RowKind::Connector) => Text::from(vec![Line::from("(connector line)")]),
        Some(RowKind::Commit(ci)) => {
            let commit = &app.data.commits[*ci];
            let mut lines: Vec<Line> = Vec::new();
            lines.push(Line::from(vec![
                Span::styled("Commit: ", Style::default().add_modifier(Modifier::BOLD)),
                Span::styled(commit.id.to_string(), Style::default().fg(Color::Yellow)),
            ]));
            lines.push(Line::from(vec![
                Span::styled("Author: ", Style::default().add_modifier(Modifier::BOLD)),
                Span::styled(format!("{} <{}>", commit.author_name, commit.author_email), Style::default().fg(Color::Blue)),
            ]));
            lines.push(Line::from(vec![
                Span::styled("Date:   ", Style::default().add_modifier(Modifier::BOLD)),
                Span::styled(format_datetime(commit.time), Style::default().fg(Color::DarkGray)),
            ]));
            if !commit.parents.is_empty() {
                let parents: Vec<String> = commit.parents.iter().map(|p| short_oid(*p)).collect();
                lines.push(Line::from(vec![
                    Span::styled("Parent: ", Style::default().add_modifier(Modifier::BOLD)),
                    Span::styled(parents.join(", "), Style::default().fg(Color::DarkGray)),
                ]));
            }
            lines.push(Line::from(""));
            for l in commit.message.lines() {
                lines.push(Line::from(l.to_string()));
            }
            Text::from(lines)
        }
        _ => Text::from(vec![Line::from("Select a commit")]),
    };
    let para = Paragraph::new(text).wrap(Wrap { trim: false });
    frame.render_widget(para, inner);
}

fn render_changed_files(frame: &mut Frame, app: &App, area: Rect) {
    let block = Block::default().title(" Changed Files ").borders(Borders::ALL).border_style(Style::default().fg(Color::DarkGray));
    let inner = block.inner(area);
    frame.render_widget(block, area);
    if inner.width == 0 || inner.height == 0 { return; }
    // Determine stats to show
    let is_uncommitted = matches!(app.selected_row().map(|r| &r.kind), Some(RowKind::Uncommitted));
    if is_uncommitted {
        if let Some(stats) = &app.data.uncommitted_stats {
            render_stats(frame, stats, inner);
            return;
        }
    }
    if app.file_stats_loading {
        frame.render_widget(Paragraph::new("Loading..."), inner);
        return;
    }
    if let Some(stats) = &app.file_stats {
        // Only show if there is a selected commit or connector (retained) - original shows retained for connector.
        // If no rows, stats is None.
        render_stats(frame, stats, inner);
    }
}
fn render_stats(frame: &mut Frame, stats: &FileStats, area: Rect) {
    let mut lines: Vec<Line> = Vec::new();
    lines.push(Line::from(vec![
        Span::styled(format!("{} files changed", stats.files_changed), Style::default().add_modifier(Modifier::BOLD)),
        Span::raw("  "),
        Span::styled(format!("+{}", stats.total_insertions), Style::default().fg(Color::Green)),
        Span::raw(" "),
        Span::styled(format!("-{}", stats.total_deletions), Style::default().fg(Color::Red)),
    ]));
    lines.push(Line::from(""));
    for f in &stats.files {
        let (_ch, color) = match f.status {
            'A' => ('A', Color::Green),
            'D' => ('D', Color::Red),
            'M' => ('M', Color::Yellow),
            c => (c, Color::White),
        };
        let mut spans = vec![Span::styled(format!(" {} ", f.status), Style::default().fg(color)), Span::raw(f.path.clone())];
        if f.insertions > 0 || f.deletions > 0 {
            spans.push(Span::raw(" "));
            spans.push(Span::styled(format!("+{}", f.insertions), Style::default().fg(Color::Green)));
            spans.push(Span::raw(" "));
            spans.push(Span::styled(format!("-{}", f.deletions), Style::default().fg(Color::Red)));
        }
        lines.push(Line::from(spans));
    }
    frame.render_widget(Paragraph::new(Text::from(lines)).wrap(Wrap { trim: false }), area);
}

fn draw(frame: &mut Frame, app: &mut App) {
    let size = frame.area();
    if size.width < 20 || size.height < 6 {
        let text = format!("Terminal too small ({}x{}). Need at least 20x6.", size.width, size.height);
        frame.render_widget(Paragraph::new(Span::styled(text, Style::default().fg(Color::Red))), size);
        return;
    }
    // vertical layout: status 1 at bottom, remaining split 70/30
    let outer = Layout::default().direction(Direction::Vertical).constraints([Constraint::Min(0), Constraint::Length(1)]).split(size);
    let main_area = outer[0];
    let status_area = outer[1];
    let chunks = Layout::default().direction(Direction::Vertical).constraints([Constraint::Percentage(70), Constraint::Percentage(30)]).split(main_area);
    let commits_area = chunks[0];
    let bottom_area = chunks[1];

    // Commits list
    {
        let block = Block::default().title(" Commits ").borders(Borders::ALL).border_style(Style::default().fg(Color::DarkGray));
        let inner = block.inner(commits_area);
        frame.render_widget(block, commits_area);
        if inner.width > 0 && inner.height > 0 {
            let items: Vec<ListItem> = (0..app.data.rows.len()).map(|i| {
                ListItem::new(build_commit_line(app, i, inner.width))
            }).collect();
            let list = List::new(items).highlight_style(Style::default().bg(Color::DarkGray).add_modifier(Modifier::BOLD));
            // need mutable list_state
            // SAFETY: we have &mut app
            frame.render_stateful_widget(list, inner, &mut app.list_state);
        }
    }
    // Bottom detail / changed files
    if bottom_area.height < 3 {
        let block = Block::default().borders(Borders::ALL).border_style(Style::default().fg(Color::DarkGray));
        frame.render_widget(block, bottom_area);
    } else if bottom_area.width >= 57 {
        let cols = Layout::default().direction(Direction::Horizontal).constraints([Constraint::Percentage(50), Constraint::Percentage(50)]).split(bottom_area);
        render_commit_detail(frame, app, cols[0]);
        render_changed_files(frame, app, cols[1]);
    } else {
        let rows_layout = Layout::default().direction(Direction::Vertical).constraints([Constraint::Percentage(50), Constraint::Percentage(50)]).split(bottom_area);
        render_commit_detail(frame, app, rows_layout[0]);
        render_changed_files(frame, app, rows_layout[1]);
    }
    render_status_bar(frame, app, status_area);

    // Branches dropdown (Normal mode only)
    if app.mode == Mode::Normal && app.error.is_none() {
        render_branches_dropdown(frame, app, commits_area);
    } else if app.mode == Mode::Normal && app.error.is_some() {
        // Original likely still shows? Keep consistent with Normal check above: we allowed only when error none.
        // To match observed error cases unknown, show it as well if in normal.
        render_branches_dropdown(frame, app, commits_area);
    }
    // Popups
    match app.mode {
        Mode::BranchInput => render_input_popup(frame, app, size),
        Mode::DeleteConfirm => render_confirm_popup(frame, app, size),
        Mode::Search => render_search_popup(frame, app, size),
        Mode::Help => render_help_popup(frame, app, size),
        Mode::Normal => {}
    }
}

fn render_branches_dropdown(frame: &mut Frame, app: &App, commits_area: Rect) {
    let Some(branches) = app.selected_branches() else { return };
    if branches.len() <= 1 { return; }
    // compute visible position of selected row
    // ListState offset: app.list_state.offset() gives first visible index in ratatui 0.30? Use offset()
    let offset = app.list_state.offset();
    if app.selected < offset { return; }
    let visible_row = (app.selected - offset) as u16;
    // commits inner top is commits_area.y+1
    let top_y = commits_area.y + 1 + visible_row + 1;
    let visible_branches: Vec<&BranchEntry> = branches.iter().take(8).collect();
    let max_name_len = branches.iter().map(|b| str_width(&b.name)).max().unwrap_or(0);
    let width = (max_name_len + 6) as u16;
    let height = (visible_branches.len() as u16) + 2;
    if commits_area.width < width + 2 { return; }
    let x = commits_area.x + commits_area.width - 2 - width + 1 - 1; // right border at commits width-3? compute: right = x+width-1 = commits.x+width-3
    // Actually: right edge index = commits_area.x + commits_area.width -3 (0-based from screen left?) if commits x=0, right = W-3
    let right = commits_area.x + commits_area.width.saturating_sub(3);
    let x = right.saturating_sub(width - 1);
    let _ = x; // silence
    let area = Rect { x: right.saturating_sub(width - 1), y: top_y, width, height };
    // If beyond screen bottom, ratatui will clip; still render
    frame.render_widget(Clear, area);
    let block = Block::default().title(" Branches").borders(Borders::ALL).border_style(Style::default().fg(Color::Blue).bg(Color::Black)).style(Style::default().bg(Color::Black));
    let inner = block.inner(area);
    frame.render_widget(block, area);
    if inner.width == 0 || inner.height == 0 { return; }
    let mut lines: Vec<Line> = Vec::new();
    for (i, b) in visible_branches.iter().enumerate() {
        if i == app.selected_branch_index.min(branches.len() - 1) {
            lines.push(Line::from(Span::styled(format!("▶ {}", b.name), Style::default().fg(Color::Black).bg(Color::Blue).add_modifier(Modifier::BOLD))));
        } else {
            lines.push(Line::from(Span::styled(format!("  {}", b.name), Style::default().fg(Color::White))));
        }
    }
    frame.render_widget(Paragraph::new(Text::from(lines)).style(Style::default().bg(Color::Black)), inner);
}

