fn render_search_popup(frame: &mut Frame, app: &App, area: Rect) {
    // width 60% centered horizontally
    let horiz = Layout::default().direction(Direction::Horizontal).constraints([Constraint::Percentage(20), Constraint::Percentage(60), Constraint::Percentage(20)]).split(area);
    let width_area = horiz[1];
    // height based on results
    let (height, lines) = build_search_lines(app, width_area.width.saturating_sub(2) as usize);
    let bottom = area.height.saturating_sub(1); // exclusive of status row
    let y = bottom.saturating_sub(height);
    let popup = Rect { x: width_area.x, y: area.y + y, width: width_area.width, height };
    frame.render_widget(Clear, popup);
    let block = Block::default().title(" Search branches ").borders(Borders::ALL).border_style(Style::default().fg(Color::Cyan).bg(Color::Black)).style(Style::default().bg(Color::Black));
    let inner = block.inner(popup);
    frame.render_widget(block, popup);
    if inner.width == 0 || inner.height == 0 { return; }
    frame.render_widget(Paragraph::new(Text::from(lines)).style(Style::default().bg(Color::Black)), inner);
}

fn build_search_lines(app: &App, inner_width: usize) -> (u16, Vec<Line<'static>>) {
    let input_line = if app.search_query.is_empty() {
        Line::from(vec![Span::raw("  "), Span::styled("_", Style::default().fg(Color::Cyan))])
    } else {
        Line::from(vec![
            Span::raw("  "),
            Span::styled(app.search_query.clone(), Style::default().fg(Color::White).add_modifier(Modifier::UNDERLINED)),
            Span::styled("_", Style::default().fg(Color::Cyan)),
        ])
    };
    if app.search_query.is_empty() {
        let lines = vec![input_line, Line::from(Span::styled("  Enter: confirm  Esc: cancel", Style::default().fg(Color::DarkGray)))];
        return (4, lines);
    }
    if app.search_results.is_empty() {
        let lines = vec![input_line, Line::from(Span::styled("  No matches", Style::default().fg(Color::DarkGray)))];
        // Original style for No matches might be default; keep dark gray as hint style? will refine from esc capture later.
        return (4, lines);
    }
    let total = app.search_results.len();
    let visible_count = total.min(7);
    let selected = app.search_index.min(total - 1);
    let start = if selected >= 7 { selected - 6 } else { 0 };
    let end = (start + visible_count).min(total);
    let mut lines = Vec::new();
    lines.push(input_line);
    lines.push(Line::from(Span::styled("─".repeat(inner_width), Style::default().fg(Color::DarkGray))));
    for idx in start..end {
        let b = &app.search_results[idx];
        let is_selected = idx == selected;
        let is_first_visible = idx == start;
        let is_last_visible = idx == end - 1;
        let prefix_char = if is_selected {
            if is_last_visible && end < total { '▼' } else { '▶' }
        } else if is_first_visible && start > 0 {
            '↑'
        } else if is_last_visible && end < total {
            '↓'
        } else {
            ' '
        };
        if is_selected {
            lines.push(Line::from(vec![
                Span::raw(format!("{} ", prefix_char)),
                Span::styled(b.name.clone(), Style::default().fg(Color::Black).bg(Color::Cyan).add_modifier(Modifier::BOLD)),
            ]));
        } else {
            let prefix = if prefix_char == ' ' { "  ".to_string() } else { format!("{} ", prefix_char) };
            lines.push(Line::from(Span::styled(format!("{}{}", prefix, b.name), Style::default().fg(Color::White))));
        }
    }
    lines.push(Line::from(Span::styled("  ↑↓: select  Enter: jump  Esc: cancel", Style::default().fg(Color::DarkGray))));
    let height = (lines.len() as u16) + 2;
    (height, lines)
}

fn render_help_popup(frame: &mut Frame, _app: &App, area: Rect) {
    let popup = centered_rect(60, 70, area);
    frame.render_widget(Clear, popup);
    let block = Block::default().title(" Help ").borders(Borders::ALL).border_style(Style::default().fg(Color::Cyan).bg(Color::Black)).style(Style::default().bg(Color::Black));
    let inner = block.inner(popup);
    frame.render_widget(block, popup);
    if inner.width == 0 || inner.height == 0 { return; }
    fn head(s: &'static str) -> Line<'static> {
        Line::from(Span::styled(s, Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)))
    }
    fn entry(k: &'static str, d: &'static str) -> Line<'static> {
        // key part is padded to 14 chars including two leading spaces in original (format "  {:<12}")
        let key_part = format!("  {:<12}", k);
        Line::from(vec![
            Span::styled(key_part, Style::default().add_modifier(Modifier::BOLD)),
            Span::styled(d, Style::default().fg(Color::White)),
        ])
    }
    let lines = vec![
        head("Navigation"),
        entry("j / ↓", "Move down"),
        entry("k / ↑", "Move up"),
        entry("] / Tab", "Select next branch"),
        entry("[ / S-Tab", "Select previous branch"),
        entry("h / ←", "Select left branch (same commit)"),
        entry("l / →", "Select right branch (same commit)"),
        entry("Ctrl+d", "Page down"),
        entry("Ctrl+u", "Page up"),
        entry("g / Home", "Go to top"),
        entry("G / End", "Go to bottom"),
        entry("@", "Jump to HEAD (current branch)"),
        Line::from(""),
        head("Git Operations"),
        entry("Enter", "Checkout selected branch/commit"),
        entry("b", "Create new branch"),
        entry("d", "Delete branch"),
        entry("f", "Fetch from origin"),
        Line::from(""),
        head("Search"),
        entry("/", "Search branches"),
        entry("↑ / C-k", "Select previous result"),
        entry("↓ / C-j", "Select next result"),
        entry("Enter", "Jump to selected branch"),
        entry("Esc", "Cancel search"),
        Line::from(""),
        head("Other"),
        entry("R", "Refresh"),
        entry("?", "Toggle this help"),
        entry("q / Esc", "Quit"),
        Line::from(""),
    ];
    frame.render_widget(Paragraph::new(Text::from(lines)).style(Style::default().bg(Color::Black)), inner);
}

// ---------- event handling ----------
fn handle_key(app: &mut App, key: KeyEvent) -> bool {
    // return true to quit
    if key.kind != KeyEventKind::Press {
        return false;
    }
    // Error takes precedence
    if app.error.is_some() {
        match key.code {
            KeyCode::Esc | KeyCode::Enter => { app.error = None; }
            KeyCode::Char('q') => { app.error = None; }
            _ => {}
        }
        return false;
    }
    match app.mode {
        Mode::Help => {
            match key.code {
                KeyCode::Esc => app.mode = Mode::Normal,
                KeyCode::Char('q') => app.mode = Mode::Normal,
                KeyCode::Char('?') => app.mode = Mode::Normal,
                _ => {}
            }
            false
        }
        Mode::BranchInput => {
            match key.code {
                KeyCode::Esc => { app.mode = Mode::Normal; app.input.clear(); }
                KeyCode::Enter => { app.do_create_branch(); }
                KeyCode::Backspace => {
                    if app.input.is_empty() {
                        app.mode = Mode::Normal;
                    } else {
                        app.input.pop();
                    }
                }
                KeyCode::Char(c) => { app.input.push(c); }
                _ => {}
            }
            false
        }
        Mode::DeleteConfirm => {
            match key.code {
                KeyCode::Char('y') | KeyCode::Enter => { app.do_delete_branch(); }
                KeyCode::Char('n') | KeyCode::Esc => { app.mode = Mode::Normal; app.pending_delete = None; }
                _ => {}
            }
            false
        }
        Mode::Search => {
            match key.code {
                KeyCode::Esc => {
                    // restore saved selection
                    app.selected = app.search_saved_selected;
                    app.selected_branch_index = app.search_saved_branch_index;
                    app.list_state.select(if app.data.rows.is_empty() { None } else { Some(app.selected.min(app.data.rows.len() - 1)) });
                    app.mode = Mode::Normal;
                    app.start_file_stats_for_selection();
                }
                KeyCode::Enter => {
                    app.mode = Mode::Normal;
                }
                KeyCode::Backspace => {
                    if app.search_query.is_empty() {
                        app.selected = app.search_saved_selected;
                        app.selected_branch_index = app.search_saved_branch_index;
                        app.list_state.select(if app.data.rows.is_empty() { None } else { Some(app.selected.min(app.data.rows.len() - 1)) });
                        app.mode = Mode::Normal;
                        app.start_file_stats_for_selection();
                    } else {
                        app.search_query.pop();
                        app.update_search_results();
                    }
                }
                KeyCode::Up => { app.search_move(-1); }
                KeyCode::Down => { app.search_move(1); }
                KeyCode::Char('j') if key.modifiers.contains(KeyModifiers::CONTROL) => { app.search_move(1); }
                KeyCode::Char('k') if key.modifiers.contains(KeyModifiers::CONTROL) => { app.search_move(-1); }
                KeyCode::Char(c) => {
                    app.search_query.push(c);
                    app.update_search_results();
                }
                _ => {}
            }
            false
        }
        Mode::Normal => {
            if key.modifiers.contains(KeyModifiers::CONTROL) {
                match key.code {
                    KeyCode::Char('d') => app.move_by(10),
                    KeyCode::Char('u') => app.move_by(-10),
                    _ => {}
                }
                return false;
            }
            match key.code {
                KeyCode::Char('q') | KeyCode::Esc => return true,
                KeyCode::Char('j') | KeyCode::Down => app.move_by(1),
                KeyCode::Char('k') | KeyCode::Up => app.move_by(-1),
                KeyCode::Char('h') | KeyCode::Left => {
                    if app.selected_branch_index > 0 { app.selected_branch_index -= 1; }
                }
                KeyCode::Char('l') | KeyCode::Right => {
                    if let Some(branches) = app.selected_branches() {
                        if !branches.is_empty() && app.selected_branch_index + 1 < branches.len() {
                            app.selected_branch_index += 1;
                        }
                    }
                }
                KeyCode::Char('g') | KeyCode::Home => app.move_to(0),
                KeyCode::Char('G') | KeyCode::End => {
                    if !app.data.rows.is_empty() { let idx = app.data.rows.len() - 1; app.move_to(idx); }
                }
                KeyCode::Char('@') => app.jump_to_head(),
                KeyCode::Char(']') | KeyCode::Tab => app.jump_next_branch(),
                KeyCode::Char('[') | KeyCode::BackTab => app.jump_prev_branch(),
                KeyCode::Enter => app.do_checkout(),
                KeyCode::Char('b') => { app.mode = Mode::BranchInput; app.input.clear(); }
                KeyCode::Char('d') => {
                    if let Some(branch) = app.selected_branch().cloned() {
                        if !branch.is_remote && !branch.is_head {
                            app.pending_delete = Some(branch.name.clone());
                            app.mode = Mode::DeleteConfirm;
                        }
                    }
                }
                KeyCode::Char('f') => {
                    app.last_fetch = Instant::now();
                    app.start_fetch(true);
                }
                KeyCode::Char('R') => {
                    app.refresh();
                }
                KeyCode::Char('/') => {
                    app.mode = Mode::Search;
                    app.search_query.clear();
                    app.search_results.clear();
                    app.search_index = 0;
                    app.search_saved_selected = app.selected;
                    app.search_saved_branch_index = app.selected_branch_index;
                }
                KeyCode::Char('?') => { app.mode = Mode::Help; }
                _ => {}
            }
            false
        }
    }
}

fn main() -> Result<()> {
    let mut cmd = Command::new("keifu")
        .version("0.2.3")
        .about("A TUI tool to visualize Git commit graphs with branch genealogy");
    let _matches = cmd.clone().get_matches();
    // clap handles help/version and errors before this point.
    let config = Config::load();
    let repo = Repository::discover(".").context("Git repository not found. Please run inside a Git repository.")?;
    let mut app = App::new(config, repo);
    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;
    let res = run_app(&mut terminal, &mut app);
    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;
    res
}

fn run_app<B: ratatui::backend::Backend>(terminal: &mut Terminal<B>, app: &mut App) -> Result<()> {
    loop {
        app.poll_async();
        terminal.draw(|f| draw(f, app))?;
        if event::poll(Duration::from_millis(100))? {
            if let Event::Key(key) = event::read()? {
                if handle_key(app, key) {
                    break;
                }
            }
        }
    }
    Ok(())
}
