import sys,os,shutil,subprocess,time
sys.path.insert(0,"/tmp"); from caplib import *
ORIG="/workspace/executable"; OURS="/tmp/ourbin"
def prep(src, destroot):
    if os.path.exists(destroot): shutil.rmtree(destroot)
    os.makedirs(destroot)
    dest=os.path.join(destroot, os.path.basename(os.path.abspath(src)))
    shutil.copytree(src,dest)
    return dest
def git_status(repo):
    env={**os.environ,"HOME":"/tmp/fakehome"}
    out=[]
    for args in [["branch","-a","-vv"],["status","--porcelain"],["rev-parse","HEAD"],["log","--all","--oneline","--graph","--decorate"]]:
        r=subprocess.run(["git"]+args,cwd=repo,env=env,capture_output=True,text=True)
        out.append(f"$ git {' '.join(args)}\n{r.stdout}{r.stderr}")
    return "\n".join(out)
def run_scenario(src, actions, width=120,height=40,config=None):
    results={}
    for label,exe in [("orig",ORIG),("ours",OURS)]:
        repo=prep(src,f"/tmp/cmp_{label}")
        # ensure clean head maybe source already
        rec=[]
        start(repo=repo,width=width,height=height,config=config,exe=exe)
        time.sleep(0.5)
        rec.append(("initial plain",cap_plain()))
        rec.append(("initial esc",cap_esc()))
        for act in actions:
            if isinstance(act,str) and act.startswith("sleep:"):
                time.sleep(float(act[6:]))
            elif isinstance(act,tuple) and act[0]=="literal":
                send_literal(act[1])
            elif isinstance(act,tuple):
                send(act,delay=0.25)
            else:
                send(act,delay=0.25)
            time.sleep(0.3)
            rec.append((f"after {act} plain",cap_plain()))
            rec.append((f"after {act} esc",cap_esc()))
        stop()
        rec.append(("git status",git_status(repo)))
        results[label]=rec
    # compare
    ok=True
    for (l1,t1),(l2,t2) in zip(results["orig"],results["ours"]):
        if t1!=t2:
            ok=False
            print(f"DIFF in {l1} src={src}")
            # write files
            open("/tmp/cmp_orig.txt","w").write(t1); open("/tmp/cmp_ours.txt","w").write(t2)
            # use python diff limited
            import difflib
            diff=list(difflib.unified_diff(t1.splitlines(),t2.splitlines(),fromfile="orig",tofile="ours",lineterm=""))
            for line in diff[:120]: print(line)
            print(f"... diff lines {len(diff)}")
            # continue maybe first diff only?
    if ok: print(f"OK {src} actions={actions}")
    return ok
if __name__=="__main__":
    import json
