    run_scenario(repo, ["j","k","Enter","b","Escape"], width=100,height=30,config=cfg)
def unstaged(repo): pathlib.Path(repo,"a.txt").write_text("hello modified\nsecond\n")
def staged(repo): pathlib.Path(repo,"new.txt").write_text("new\n"); git(repo,"add","new.txt")
def untracked(repo): pathlib.Path(repo,"u.txt").write_text("u\n")
def deleted(repo): os.remove(os.path.join(repo,"a.txt"))
def both(repo):
    pathlib.Path(repo,"a.txt").write_text("stage1\n"); git(repo,"add","a.txt"); pathlib.Path(repo,"a.txt").write_text("stage1\nwork2\n")
    pathlib.Path(repo,"b.txt").write_text("bstage\n"); git(repo,"add","b.txt")
def rename(repo): git(repo,"mv","a.txt","renamed.txt")
for name,fn in [("unstaged",unstaged),("staged",staged),("untracked",untracked),("deleted",deleted),("both",both),("rename",rename)]:
    prepare(name,fn)
