new="""    fn refresh(&mut self) {
        let repo_opt = Repository::open(&self.repo_path).or_else(|_| Repository::discover(&self.repo_path));
        if let Ok(repo) = repo_opt {
            let saved_branch_name = self.selected_branch_name.clone();
            self.data = load_repo_data(repo);
            self.clamp_selection();
            if let Some(name) = saved_branch_name {
                if let Some(branches) = self.selected_branches() {
