fn build_connector_cells(lanes: &[Option<LaneState>], to: usize, merges: &[usize]) -> Vec<GraphCell> {
    let slots = lanes.len();
    let mut cells: Vec<GraphCell> = vec![GraphCell { ch: ' ', color: None }; slots * 2];
    for i in 0..slots {
        if let Some(lane) = &lanes[i] {
            cells[i * 2] = GraphCell { ch: '│', color: Some(lane.color) };
        }
    }
    let mut sorted = merges.to_vec();
    sorted.sort_unstable();
    let to_color = lanes.get(to).and_then(|l| l.as_ref()).map(|l| l.color).unwrap_or_else(|| lane_color(to));
    for &from in &sorted {
        let src_color = lanes.get(from).and_then(|l| l.as_ref()).map(|l| l.color).unwrap_or_else(|| lane_color(from));
        if from > to {
            cells[to * 2] = GraphCell { ch: '├', color: Some(to_color) };
            for x in (to * 2 + 1)..(from * 2) {
                if x % 2 == 0 {
                    let lane = x / 2;
                    if sorted.contains(&lane) {
                        let c = lanes.get(lane).and_then(|l| l.as_ref()).map(|l| l.color).unwrap_or_else(|| lane_color(lane));
                        cells[x] = GraphCell { ch: '┴', color: Some(c) };
                    } else if lanes.get(lane).map(|l| l.is_some()).unwrap_or(false) {
                        let c = lanes.get(lane).and_then(|l| l.as_ref()).map(|l| l.color).unwrap_or_else(|| lane_color(lane));
                        cells[x] = GraphCell { ch: '┼', color: Some(c) };
                    } else {
                        cells[x] = GraphCell { ch: '─', color: Some(src_color) };
                    }
                } else {
                    cells[x] = GraphCell { ch: '─', color: Some(src_color) };
                }
            }
            cells[from * 2] = GraphCell { ch: '╯', color: Some(src_color) };
        } else if from < to {
            cells[to * 2] = GraphCell { ch: '┤', color: Some(to_color) };
            for x in (from * 2 + 1)..(to * 2) {
                if x % 2 == 0 {
                    let lane = x / 2;
                    if sorted.contains(&lane) {
                        let c = lanes.get(lane).and_then(|l| l.as_ref()).map(|l| l.color).unwrap_or_else(|| lane_color(lane));
                        cells[x] = GraphCell { ch: '┴', color: Some(c) };
                    } else if lanes.get(lane).map(|l| l.is_some()).unwrap_or(false) {
                        let c = lanes.get(lane).and_then(|l| l.as_ref()).map(|l| l.color).unwrap_or_else(|| lane_color(lane));
                        cells[x] = GraphCell { ch: '┼', color: Some(c) };
                    } else {
                        cells[x] = GraphCell { ch: '─', color: Some(src_color) };
                    }
                } else {
                    cells[x] = GraphCell { ch: '─', color: Some(src_color) };
                }
            }
            cells[from * 2] = GraphCell { ch: '╰', color: Some(src_color) };
        }
    }
    cells
}

fn build_commit_cells(
    lanes_before: &[Option<LaneState>],
    lanes_after_alloc: &[Option<LaneState>],
    width_slots: usize,
    column: usize,
    commit: &CommitInfo,
    merge_edges: &[usize],
    new_lane_for_parent: &HashMap<Oid, usize>,
) -> Vec<GraphCell> {
    let mut cells: Vec<GraphCell> = vec![GraphCell { ch: ' ', color: None }; width_slots * 2];
    let lane_color_at = |i: usize| -> Color {
        if let Some(Some(l)) = lanes_before.get(i) { l.color }
        else if let Some(Some(l)) = lanes_after_alloc.get(i) { l.color }
        else { lane_color(i) }
    };
    for i in 0..width_slots {
        let active = if i < lanes_before.len() { lanes_before[i].is_some() } else { false };
        if i == column {
            cells[i * 2] = GraphCell { ch: '●', color: Some(lane_color_at(i)) };
        } else if active {
            cells[i * 2] = GraphCell { ch: '│', color: Some(lane_color_at(i)) };
        }
    }
    let mut drawn_up_to: Option<usize> = None;
    for (idx, &target) in merge_edges.iter().enumerate() {
        let parent = commit.parents[idx + 1];
        let is_new = new_lane_for_parent.get(&parent).map(|&i| i == target).unwrap_or(false);
        let tcolor = lane_color_at(target);
        if target > column {
            let start_x = column * 2;
            let end_x = target * 2;
            for x in (start_x + 1)..end_x {
                if let Some(up) = drawn_up_to { if x <= up { continue; } }
                if x % 2 == 0 {
                    let lane = x / 2;
                    let was_active = lane < lanes_before.len() && lanes_before[lane].is_some();
                    if was_active && lane != column {
                        cells[x] = GraphCell { ch: '┼', color: Some(lane_color_at(lane)) };
                    } else {
                        cells[x] = GraphCell { ch: '─', color: Some(tcolor) };
                    }
                } else {
                    cells[x] = GraphCell { ch: '─', color: Some(tcolor) };
                }
            }
            cells[end_x] = GraphCell { ch: if is_new { '╮' } else { '┤' }, color: Some(tcolor) };
            drawn_up_to = Some(end_x);
        } else if target < column {
            let start_x = target * 2;
            let end_x = column * 2;
            for x in (start_x + 1)..end_x {
                if x % 2 == 0 {
                    let lane = x / 2;
                    let was_active = lane < lanes_before.len() && lanes_before[lane].is_some();
                    if was_active {
                        cells[x] = GraphCell { ch: '┼', color: Some(lane_color_at(lane)) };
                    } else {
                        cells[x] = GraphCell { ch: '─', color: Some(tcolor) };
                    }
                } else {
                    cells[x] = GraphCell { ch: '─', color: Some(tcolor) };
                }
            }
            cells[start_x] = GraphCell { ch: if is_new { '╭' } else { '├' }, color: Some(tcolor) };
        }
    }
    cells
}

