use git2::*;
fn main(){
 let path=std::env::args().nth(1).unwrap(); let repo=Repository::open(&path).unwrap(); let head=repo.head().unwrap().peel_to_commit().unwrap(); let tree=head.tree().unwrap(); let parent=head.parent(0).unwrap().tree().unwrap();
 let diff=repo.diff_tree_to_tree(Some(&parent),Some(&tree),None).unwrap();
 println!("deltas {}",diff.deltas().len());
 diff.print(DiffFormat::Patch,|delta,hunk,line|{ let d=delta.map(|d| format!("{:?} {:?}->{:?}",d.status(),d.old_file().path(),d.new_file().path())).unwrap_or_default(); println!("PRINT delta={d} hunk={} origin={} content={:?}",hunk.is_some(),line.origin(),String::from_utf8_lossy(line.content())); true}).unwrap();
 println!("--- foreach");
 diff.foreach(&mut |delta,_|{println!("file cb {:?} {:?}->{:?}",delta.status(),delta.old_file().path(),delta.new_file().path()); true},None,Some(&mut |delta,hunk|{println!("hunk cb {:?} {:?}",delta.map(|d|d.status()), String::from_utf8_lossy(hunk.header())); true}),Some(&mut |delta,_,line|{println!("line cb {:?} {} {:?}",delta.map(|d|d.status()),line.origin(),String::from_utf8_lossy(line.content())); true})).unwrap();
