new=r'''fn diff_to_stats(diff: &git2::Diff, cap: usize, count_override: Option<usize>) -> FileStats {
    let total_files = count_override.unwrap_or_else(|| diff.deltas().len());
    // First compute patch stats for the first `cap` deltas, aggregating by path.
    // (A typechange is split into a Deleted and an Added delta for the same
    // path; the original aggregates their line counts into the first entry.)
    let mut per_delta: Vec<(String, char, usize, usize)> = Vec::new();
    let mut aggregate: HashMap<String, (usize, usize)> = HashMap::new();
    for (i, delta) in diff.deltas().enumerate().take(cap) {
        let (status, _c) = status_char_and_color(delta.status());
        let path = delta
            .new_file()
            .path()
            .or_else(|| delta.old_file().path())
            .map(|p| p.to_string_lossy().to_string())
            .unwrap_or_default();
        let (ins, del) = match git2::Patch::from_diff(diff, i) {
            Ok(Some(patch)) => match patch.line_stats() {
                Ok((_, a, d)) => (a, d),
                Err(_) => (0, 0),
            },
            _ => (0, 0),
        };
        let e = aggregate.entry(path.clone()).or_insert((0, 0));
        e.0 += ins;
        e.1 += del;
        per_delta.push((path, status, ins, del));
    }
    let mut files = Vec::new();
    let mut seen_paths: HashSet<String> = HashSet::new();
    let mut total_insertions = 0usize;
    let mut total_deletions = 0usize;
    for (path, status, _ins, _del) in per_delta {
        let (ins, del) = if seen_paths.insert(path.clone()) {
            aggregate.get(&path).cloned().unwrap_or((0, 0))
        } else {
            (0, 0)
        };
        total_insertions += ins;
        total_deletions += del;
        files.push(FileStat { path, status, insertions: ins, deletions: del });
    }
    FileStats { files_changed: total_files, total_insertions, total_deletions, files }
}

'''
