end=s.index("fn load_repo_data")
new2=r'''    // Combine staged and unstaged stats: entries from the staged diff first,
    // then unstaged entries whose path has not already been seen.
    let staged_stats = diff_to_stats(&staged, 50, None);
    let unstaged_stats = diff_to_stats(&unstaged, 50, None);
    let mut files: Vec<FileStat> = staged_stats.files.clone();
    let mut seen: HashSet<String> = files.iter().map(|f| f.path.clone()).collect();
    for f in unstaged_stats.files.iter() {
        if seen.insert(f.path.clone()) {
            files.push(f.clone());
        }
    }
    files.truncate(50);
    let stats = FileStats {
        files_changed: files.len(),
        total_insertions: staged_stats.total_insertions + unstaged_stats.total_insertions,
        total_deletions: staged_stats.total_deletions + unstaged_stats.total_deletions,
        files,
    };
    Some((count, stats))
}

'''
