p=pathlib.Path("src/main.rs"); s=p.read_text()
# Add cycle_branch method before branch_row_indices
old="""    fn branch_row_indices(&self) -> Vec<usize> {"""
new="""    fn cycle_branch(&mut self, dir: i64) {
        let Some(ci) = self.selected_commit_idx() else { return };
        let display_branches = match self.data.commit_branches.get(ci) { Some(v) => v.clone(), None => return };
        if display_branches.is_empty() { return; }
        let displayed_idx = self.selected_branch_index.min(display_branches.len() - 1);
        let current_name = match &self.selected_branch_name {
            Some(name) if display_branches.iter().any(|b| &b.name == name) => name.clone(),
            _ => display_branches[displayed_idx].name.clone(),
        };
        let Some(current_pos) = display_branches.iter().position(|b| b.name == current_name) else { return };
        let new_pos_i = current_pos as i64 + dir;
        if new_pos_i < 0 || new_pos_i as usize >= display_branches.len() { return; }
        let next_branch = display_branches[new_pos_i as usize].clone();
        let commit_id = self.data.commits[ci].id;
        let raw_idx = self.data.raw_branches.iter().filter(|b| b.target == commit_id).position(|b| b.name == next_branch.name && b.is_remote == next_branch.is_remote);
        self.selected_branch_index = raw_idx.unwrap_or(new_pos_i as usize);
        self.selected_branch_name = Some(next_branch.name.clone());
    }
    fn branch_row_indices(&self) -> Vec<usize> {"""
assert old in s; s=s.replace(old,new)
# Replace h/l handlers
old_h="""                KeyCode::Char('h') | KeyCode::Left => {
                    if app.selected_branch_index > 0 { app.selected_branch_index -= 1; app.selected_branch_name = app.selected_branch().map(|b| b.name.clone()); }
                }"""
new_h="""                KeyCode::Char('h') | KeyCode::Left => {
                    app.cycle_branch(-1);
                }"""
assert old_h in s; s=s.replace(old_h,new_h)
old_l="""                KeyCode::Char('l') | KeyCode::Right => {
                    if let Some(branches) = app.selected_branches() {
                        if !branches.is_empty() && app.selected_branch_index + 1 < branches.len() {
                            app.selected_branch_index += 1;
                            app.selected_branch_name = app.selected_branch().map(|b| b.name.clone());
                        }
                    }
                }"""
new_l="""                KeyCode::Char('l') | KeyCode::Right => {
                    app.cycle_branch(1);
                }"""
assert old_l in s; s=s.replace(old_l,new_l)
p.write_text(s)
